Scores a fixed continuation after a fixed prompt (``tools/greedy/oa.json``) and
compares per-token logprobs against a saved reference.  The continuation is
teacher-forced, so the result does not depend on what the model generated.  A
wrong kernel or a mis-set flag moves the logprobs by orders of magnitude more
than run-to-run noise.

  python3 logprob_diff.py save  NAME
  python3 logprob_diff.py check NAME     # max/mean |dlogprob| vs NAME
  python3 logprob_diff.py compare A B    # symmetric: B vs A
"""
import json, os, sys, urllib.request

URL = os.environ.get("SGLANG_URL", ""    LOGPROB_MAX={overall['max']:.6f} LOGPROB_MEAN={overall['mean']:.6f}")


def main() -> None:
    if len(sys.argv) < 2:
        print(__doc__)
        sys.exit(1)
    cmd = sys.argv[1]
    if cmd == "save":
        name = sys.argv[2]
        path = D / f"{name}.json"
        path.write_text(json.dumps(collect(), indent=2))
        print(f"  saved {path}")
    elif cmd == "check":
        ref = json.loads((D / f"{sys.argv[2]}.json").read_text())
        cur = collect(cached=ref)
        report = stats(ref, cur)
        print_report(f"{sys.argv[2]} vs current", report)
    elif cmd == "compare":
        a = json.loads((D / f"{sys.argv[2]}.json").read_text())
        b = json.loads((D / f"{sys.argv[3]}.json").read_text())
        report = stats(a, b)
        print_report(f"{sys.argv[3]} vs {sys.argv[2]}", report)
    else:
        print(__doc__)
        sys.exit(1)


if __name__ == "__main__":
    main()


